    Bug 1990129 - Update folder on successful imap append for both nsImapAppend* URLs. r=mkmelin

    nsImapMailFolder::OnStopRunningUrl() was calling UpdateFolderWithListener() only
    for nsImapAppendDraftFromFile and not for nsImapAppendMsgFromFile. Now calls it
    for both.

    Differential Revision: https://phabricator.services.mozilla.com/D266563

diff --git a/mailnews/imap/src/nsImapMailFolder.cpp b/mailnews/imap/src/nsImapMailFolder.cpp
index 88e39e9d147..67a455e5856 100644
--- a/mailnews/imap/src/nsImapMailFolder.cpp
+++ b/mailnews/imap/src/nsImapMailFolder.cpp
@@ -5065,9 +5065,7 @@ nsImapMailFolder::OnStopRunningUrl(nsIURI* aUrl, nsresult aExitCode) {
                   }
                 }
                 (void)OnCopyCompleted(m_copyState->m_srcSupport, aExitCode);
-                if (imapAction == nsIImapUrl::nsImapAppendDraftFromFile) {
-                  UpdateFolderWithListener(msgWindow, m_urlListener);
-                }
+                UpdateFolderWithListener(msgWindow, m_urlListener);
               }
             } else {
               // clear the copyState if copy has failed
